    if (typeof x === 'string') return { n: x || 'Band ' + (i + 1), kg: null };
    if (x && typeof x === 'object') return { n: String((x as Obj).n || 'Band ' + (i + 1)), kg: (x as Obj).kg == null || (x as Obj).kg === '' ? null : +(x as Obj).kg };
